import{_ as a}from"./chunks/tank_survival.DwbhvMmU.js";import{_ as t,o as s,c as r,a5 as i}from"./chunks/framework.DrDMl0tG.js";const o="/assets/tank_survival_town.DMwDXQWB.jpg",n="/assets/tank_survival_fortress.C-PKdCsK.jpg",w=JSON.parse('{"title":"Rayrai Example: Tank Survival","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/rayrai/rayrai_tank_survival.md","filePath":"sections/examples/rayrai/rayrai_tank_survival.md"}'),l={name:"sections/examples/rayrai/rayrai_tank_survival.md"};function h(d,e,c,p,m,u){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rayrai-example-tank-survival" tabindex="-1">Rayrai Example: Tank Survival <a class="header-anchor" href="#rayrai-example-tank-survival" aria-label="Permalink to &quot;Rayrai Example: Tank Survival&quot;">​</a></h1><p><img src="'+a+'" alt="A Leopard 2 firing its machine gun among scrub and broadleaf trees in the endless survival level, the river behind it"></p><p><em>The vehicles are licensed under CC BY 4.0 and credited in <a href="./../../AssetCredits.html#tank-survival-vehicles">Asset Credits</a>; the props, plants, buildings and textures are Poly Haven assets under CC0.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A tank survival game in six levels, each with its own terrain and weather: a green valley at noon, desert dunes in a crosswind, a ruined town under an overcast sky, snow ridges in the late afternoon, a fortress assault and an endless survival. Enemy vehicles arrive in waves around your Leopard 2: scouts, tanks, tank destroyers that snipe from range, self-propelled guns that mark their target before the shells land, and heavily armored brutes. The same source builds for the desktop and, with the <a href="./../../WebAssemblySdk.html">WebAssembly SDK</a>, for the browser.</p><p><img src="'+o+'" alt="Ruined Town: apartment blocks assembled from modular facades, with burnt-out ones among them"></p><ul><li>Every shell is a RaiSim <a href="./../../Explosions.html#projectiles">projectile</a>: it drifts with the wind (the world&#39;s air, <code>World::setAmbientFluid()</code>) and slows down in water. Hits are resolved against the front, side, rear and roof armor of the vehicle they strike, with ricochets at shallow angles.</li><li>High-explosive shells, missiles, artillery and exploding barrels set off <a href="./../../Explosions.html">explosions</a> whose blast waves push tanks, wrecks, crates and barrels and dig craters in the terrain. Wrecks burn.</li><li>The tanks are articulated systems on <a href="./../../articulated_system/Tracks.html">tracks</a>, each track on a carrier sprung under the hull so that the tracks keep their grip on rough ground and the tanks can steer. A river crosses each level as a fluid volume: tanks wade through it, are slowed and buoyed by it, and push its water aside.</li><li>rayrai draws the explosions as fireballs, smoke, dust and debris with soft particles (<a href="./../../rayrai/Explosions.html">Explosion effects</a>), the river with its flow, the weather of each level, and rough terrain planted with trees, shrubs and grass that keep their detail far from the camera. The town is built from Poly Haven&#39;s modular apartment facades, as in the <a href="./rayrai_city.html">City</a> example.</li><li>Weapons: armor-piercing and high-explosive shells, a coaxial machine gun, guided missiles, artillery strikes and a smoke screen. Pickups bring ammunition, repairs, reactive armor, missiles and radios.</li></ul><p><img src="'+n+`" alt="Iron Fortress: crenellated walls and towers around the enemy&#39;s stronghold, across the river"></p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p>Aiming works as in a third-person shooter. Click the view once to capture the mouse (<code>Esc</code> frees it and pauses).</p><table tabindex="0"><thead><tr><th>Input</th><th>Action</th></tr></thead><tbody><tr><td><code>W</code> / <code>S</code>, <code>A</code> / <code>D</code></td><td>drive, turn the hull</td></tr><tr><td>mouse</td><td>look and aim over the tank&#39;s shoulder; every round lands where the crosshair in the middle of the view is</td></tr><tr><td>left click or <code>Space</code></td><td>fire</td></tr><tr><td>hold the right button</td><td>aim down the sight: the view from the gun, ×3; the wheel zooms from ×2 to ×8</td></tr><tr><td>mouse wheel</td><td>move the camera closer or farther</td></tr><tr><td><code>1</code>–<code>5</code>, <code>Q</code> / <code>E</code></td><td>pick a weapon, cycle through them</td></tr><tr><td><code>F</code></td><td>lay a smoke screen</td></tr><tr><td><code>C</code></td><td>camera behind the tank</td></tr><tr><td><code>P</code> or <code>Esc</code> / hold <code>R</code> / <code>H</code></td><td>pause, restart, how to play</td></tr></tbody></table><p>The gun of your tank is stabilized, and each round leaves the muzzle on the path that reaches the point under the crosshair (a vehicle, a wall, a tree or the ground): the game flies it ahead of time as the world will, with gravity, the air&#39;s drag and the wind. After a quick turn of the view, a click fires as soon as the turret has swung round to the crosshair. The crosshair turns red over an enemy. On a touch screen, where the mouse cannot be captured, tap where to aim: the sight locks on an enemy near the tap, and a dotted arc shows where a round would fly, to a ring where it would strike. The <strong>How to play</strong> button (or <code>H</code>) opens the controls; they come up before the first mission. Arrows at the edge of the screen point to enemies out of view, and an arrow beside the wind&#39;s speed shows where it blows. Tanks flatten the small trees of the arena, and shells and blasts fell them.</p><p>The menu shows your best score on each level; in the browser it is kept between visits (in the page&#39;s local storage). On a slow computer the main menu lowers the render quality while the level behind it draws slowly, until it runs smoothly (the game itself slows down below 25 frames a second); a quality picked in the menu, or given with <code>--quality</code>, is kept.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>The game is one program, <a href="https://github.com/raisimTech/raisim2Lib/tree/master/wasm/src/tank_survival" target="_blank" rel="noreferrer"><code>raisim2Lib/wasm/src/tank_survival</code></a>, built for the desktop with the other examples and for the browser with the WebAssembly SDK; both builds play and look the same. On the desktop:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-examples</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rayrai_tank_survival</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tank_survival</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tank_survival</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --autopilot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --quality</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span></code></pre></div><p><code>--level N</code> starts the Nth level, <code>--autopilot</code> lets the tank play itself, <code>--quality 0-3</code> picks Fast, Balanced, High or Ultra rendering, and <code>--frames N --screenshot file.png</code> saves the Nth frame. For the browser, build <a href="https://github.com/raisimTech/raisim2Lib/tree/master/wasm" target="_blank" rel="noreferrer"><code>raisim2Lib/wasm</code></a> with Emscripten and the SDK as the <a href="./../../WebAssemblySdk.html#quick-start">WebAssembly SDK</a> page describes, or <a href="https://raisim.com/games/tank-survival/" target="_blank" rel="noreferrer">play it on this website</a>. The <a href="./rayrai_explosion_projectile.html">Explosion and Projectile</a> example shows the explosion and projectile API on its own.</p>`,17)])])}const b=t(l,[["render",h]]);export{w as __pageData,b as default};
